INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (633, 'Slow Cooker BBQ Chicken Sliders', 'Spend With Pennies', 'https://www.spendwithpennies.com/slow-cooker-bacon-barbecue-chicken-sliders/', 390, 25, 0, 18, 18, 0, 18, 'slider', '1. Fry the bacon until crisp and drain it, saving 2 tablespoons of the grease. | 2. Cook the onion with the salt in the grease until tender and spread it in the bottom of a 6-quart slow cooker. | 3. Add the water to the pan, scrape up the browned bits and pour them in. | 4. Add the chicken and barbecue sauce, stir, and cook on low 7 to 8 hours or high 4 to 5 hours. | 5. Shred the chicken, stir in half the bacon and pile onto the rolls with the remaining bacon.', NULL);
