INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (690, 'Pork and Sauerkraut', 'Budget Bytes', 'https://www.budgetbytes.com/pork-and-sauerkraut/', 230, 45, 0, 8, 8, 0, NULL, NULL, '1. Heat the oven to 300°F and season the pork with salt, pepper and garlic powder. | 2. Sear the pork in oil in a Dutch oven until deep golden, 8 to 10 minutes, and set aside. | 3. Cook the onion and apples until soft, then stir in the garlic, brown sugar, mustard, caraway, paprika, pepper and bay leaf for a minute. | 4. Stir in the sauerkraut and broth, set the pork on top, cover and roast 3 to 3½ hours until tender. | 5. Uncover, raise the oven to 375°F and roast 20 to 30 minutes, then rest the pork 10 minutes, shred it and fold it into the sauerkraut.', NULL);
