INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (691, 'Honey Mustard Pork Chops', 'Budget Bytes', 'https://www.budgetbytes.com/honey-mustard-pork-chops/', 55, 35, 0, 4, 4, 0, NULL, NULL, '1. Heat the oven to 350°F and stir the mayonnaise, Dijon, honey, garlic powder, paprika, salt and pepper into a sauce. | 2. Pat the chops dry, season both sides and sear in hot oil two at a time, about 3 minutes per side. | 3. Put the chops in a casserole dish and spread the sauce over them. | 4. Bake until they reach 145°F, 20 to 30 minutes, then broil 3 to 5 minutes until golden and bubbly.', NULL);
