INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (692, 'Soy Dijon Pork Tenderloin', 'Budget Bytes', 'https://www.budgetbytes.com/soy-dijon-pork-tenderloin/', 165, 40, 0, 4, 4, 0, NULL, NULL, '1. Whisk the Dijon, soy sauce, 2 Tbsp olive oil, brown sugar, pepper and garlic, coat the pork in a zip-top bag and marinate in the fridge at least 2 hours. | 2. Heat the oven to 400°F, drain the pork and sear in 1 Tbsp olive oil about 5 minutes per side. | 3. Roast on a foil-lined sheet about 30 minutes until 145°F, then rest 5 to 10 minutes and slice. | 4. Optional pan sauce: melt the butter in the skillet, whisk in Dijon, brown sugar and broth and simmer until reduced by half.', NULL);
