INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (693, 'Potato and Green Bean Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/potato-and-green-bean-skillet/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Boil the halved potatoes in salted water 7 to 8 minutes until tender and drain. | 2. Crisp the bacon in a large skillet, remove it and leave at least 2 Tbsp fat in the pan. | 3. Cook the onion in the bacon fat until soft, add the potatoes and let them brown. | 4. Add the frozen green beans and heat through. | 5. Chop the bacon, stir it back in with the seasoning and serve hot.', NULL);
