INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (1382, 'Parmesan Baked Eggs over Bacon, Mushroom and Leek Hash', 'Food52', 'https://www.food52.com/recipes/10814-parmesan-baked-eggs-over-bacon-mushroom-leek-and-arugula-hash', 30, 25, 1, 1, 2, 1, NULL, NULL, '1. Heat the oven to 350 degrees. | 2. Fry the chopped bacon in a hot cast-iron skillet until nearly crisp and move it to a bowl with a quarter of the bacon grease. | 3. Saute the mushrooms and leeks in the remaining grease about 3 minutes until tender. | 4. Add the garlic and arugula and saute 1 minute, then return the bacon. | 5. Spread the hash in the skillet, make wells for the eggs, crack them in and top with Parmesan, cayenne and pepper. | 6. Bake until the whites are set.', NULL);
