INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (1448, 'Chicken Broccoli Casserole', 'Cookbooks.com', 'https://www.cookbooks.com/Recipe-Details.aspx?id=8085', 60, 20, 1, 6, 6, 0, NULL, NULL, '1. Heat the oven to 375 degrees and butter a casserole dish. | 2. Cut the broccoli into bite-size pieces and put it in the dish. | 3. Cut up the cooked chicken and arrange it over the broccoli. | 4. Mix the cream of chicken soup and mayonnaise, spread over the chicken and broccoli, then top with the cheese and bread crumbs. | 5. Bake about 45 minutes.', NULL);
