INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (1449, 'Ginger Beef and Broccoli', 'MyRecipes', 'https://www.myrecipes.com/recipe/ginger-beef-broccoli', 30, 30, 0, 4, 4, 1, NULL, NULL, '1. Slice the beef crosswise into 1/4-inch-thick slices about 2 inches long. | 2. Cut the florets off the broccoli, peel and slice the stalks and cut the pepper into thin strips, then combine the broccoli and pepper in a bowl. | 3. Stir the beef broth, soy sauce, ginger, garlic and cornstarch together until the cornstarch dissolves. | 4. Heat the oil in a large skillet or wok over high heat and stir-fry the beef until browned, then add the broccoli and pepper and cook until crisp-tender. | 5. Pour in the sauce and cook, stirring, until thickened.', NULL);
