INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (1491, 'Cornflake-Coated Pork Chops', 'MyRecipes', 'https://www.myrecipes.com/recipe/cornflake-coated-pork-chops', 50, 20, 1, 6, 6, 1, NULL, NULL, '1. Heat the oven to 350 degrees. | 2. Stir the eggs and milk together in a shallow dish and put the cornflake crumbs in another. | 3. Sprinkle the pork with the lemon pepper, salt and garlic powder. | 4. Dip the chops in the egg mixture, dredge in the crumbs and set them on a lightly greased rack on a baking sheet. | 5. Bake 30 to 35 minutes until done and squeeze the lemon over the chops.', NULL);
