INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (1517, 'Eggs Benedict with Homemade Hollandaise', 'Taste of Home', 'https://www.tasteofhome.com/recipes/eggs-benedict-with-homemade-hollandaise/', 40, 40, 1, 4, 4, 1, NULL, NULL, '1. For the hollandaise, whisk the egg yolks, water and lemon juice in a double boiler or a metal bowl over simmering water until the mixture coats a spoon and reaches 160 degrees. | 2. Remove from the heat and slowly drizzle in the warm melted butter, whisking constantly, then whisk in the white pepper and keep the sauce warm. | 3. Poach the eight eggs in simmering water until the whites are set. | 4. Set two Canadian bacon slices on each toasted English muffin half pair, top with the poached eggs and spoon over the hollandaise, then sprinkle with paprika.', NULL);
